import React, { useState } from 'react';
import { ManualFilterParams, ManualCategory } from '../types';

interface ManualFiltersProps {
  filters: ManualFilterParams;
  categories: ManualCategory[];
  onFilterChange: (filters: ManualFilterParams) => void;
  onReset: () => void;
}

const ManualFilters: React.FC<ManualFiltersProps> = ({
  filters,
  categories,
  onFilterChange,
  onReset,
}) => {
  // 검색 입력 상태 (실시간 반영 방지)
  const [keyword, setKeyword] = useState(filters.keyword || '');
  const [startDate, setStartDate] = useState(filters.startDate || '');
  const [endDate, setEndDate] = useState(filters.endDate || '');

  // 검색 버튼 클릭
  const handleSearch = () => {
    onFilterChange({
      ...filters,
      keyword: keyword.trim() || undefined,
      startDate: startDate || undefined,
      endDate: endDate || undefined,
      page: 0, // 검색 시 첫 페이지로
    });
  };

  // 카테고리 필터 변경
  const handleCategoryFilterChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const value = e.target.value;
    onFilterChange({
      ...filters,
      categoryId: value === 'all' ? undefined : value,
      page: 0, // 필터 변경 시 첫 페이지로
    });
  };

  // 필터 초기화
  const handleReset = () => {
    setKeyword('');
    setStartDate('');
    setEndDate('');
    onReset();
  };

  // Enter 키로 검색
  const handleKeyPress = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      handleSearch();
    }
  };

  return (
    <div className="bg-white rounded-lg shadow-sm p-4 mb-6 space-y-4">
      {/* 검색 및 날짜 필터 */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {/* 키워드 검색 */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            검색어
          </label>
          <input
            type="text"
            placeholder="제목, 내용, 카테고리명 검색..."
            value={keyword}
            onChange={(e) => setKeyword(e.target.value)}
            onKeyPress={handleKeyPress}
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          />
        </div>

        {/* 카테고리 필터 */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            카테고리
          </label>
          <select
            value={filters.categoryId || 'all'}
            onChange={handleCategoryFilterChange}
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          >
            <option value="all">전체</option>
            {categories
              .filter((cat) => cat.isActive)
              .map((category) => (
                <option key={category.id} value={category.id}>
                  {category.name}
                </option>
              ))}
          </select>
        </div>

        {/* 시작 날짜 */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            시작 날짜
          </label>
          <input
            type="date"
            value={startDate}
            onChange={(e) => setStartDate(e.target.value)}
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          />
        </div>

        {/* 종료 날짜 */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            종료 날짜
          </label>
          <input
            type="date"
            value={endDate}
            onChange={(e) => setEndDate(e.target.value)}
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          />
        </div>
      </div>

      {/* 검색 버튼 및 필터 초기화 */}
      <div className="flex justify-end gap-2">
        <button
          onClick={handleReset}
          className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition-colors"
        >
          필터 초기화
        </button>
        <button
          onClick={handleSearch}
          className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
        >
          검색
        </button>
      </div>
    </div>
  );
};

export default ManualFilters;
