import React from 'react';
import { HostListFilterParams } from '../types';
import { debounce } from '../utils/searchUtils';

interface HostListFiltersProps {
  filters: HostListFilterParams;
  onFilterChange: (filters: HostListFilterParams) => void;
  onReset: () => void;
}

const HostListFilters: React.FC<HostListFiltersProps> = ({
  filters,
  onFilterChange,
  onReset,
}) => {
  const [searchTerm, setSearchTerm] = React.useState(filters.searchTerm || '');

  // 디바운스된 검색어 업데이트
  const debouncedUpdateSearch = React.useMemo(
    () =>
      debounce((term: string) => {
        onFilterChange({ ...filters, searchTerm: term || undefined });
      }, 300),
    [filters, onFilterChange]
  );

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setSearchTerm(value);
    debouncedUpdateSearch(value);
  };

  const handleBankbookFilterChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const value = e.target.value;
    onFilterChange({
      ...filters,
      hasBankbook: value === 'all' ? undefined : value === 'true',
    });
  };

  const handleStaysFilterChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const value = e.target.value;
    onFilterChange({
      ...filters,
      hasStays: value === 'all' ? undefined : value === 'true',
    });
  };

  const handleSortFieldChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    onFilterChange({
      ...filters,
      sortField: e.target.value as 'hostName' | 'createdDate' | 'updatedDate',
    });
  };

  const handleSortDirectionChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    onFilterChange({
      ...filters,
      sortDirection: e.target.value as 'ASC' | 'DESC',
    });
  };

  return (
    <div className="bg-white rounded-lg shadow-sm p-4 mb-6 space-y-4">
      {/* 검색 */}
      <div>
        <input
          type="text"
          placeholder="호스트명, 연락처, ID 검색..."
          value={searchTerm}
          onChange={handleSearchChange}
          className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
        />
      </div>

      {/* 필터 및 정렬 */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {/* 통장사본 필터 */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            통장사본
          </label>
          <select
            value={
              filters.hasBankbook === undefined
                ? 'all'
                : filters.hasBankbook
                ? 'true'
                : 'false'
            }
            onChange={handleBankbookFilterChange}
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          >
            <option value="all">전체</option>
            <option value="true">있음</option>
            <option value="false">없음</option>
          </select>
        </div>

        {/* Stay 연결 필터 */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Stay 연결
          </label>
          <select
            value={
              filters.hasStays === undefined
                ? 'all'
                : filters.hasStays
                ? 'true'
                : 'false'
            }
            onChange={handleStaysFilterChange}
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          >
            <option value="all">전체</option>
            <option value="true">있음</option>
            <option value="false">없음</option>
          </select>
        </div>

        {/* 정렬 기준 */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            정렬 기준
          </label>
          <select
            value={filters.sortField || 'createdDate'}
            onChange={handleSortFieldChange}
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          >
            <option value="hostName">호스트명</option>
            <option value="createdDate">생성일</option>
            <option value="updatedDate">수정일</option>
          </select>
        </div>

        {/* 정렬 방향 */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            정렬 방향
          </label>
          <select
            value={filters.sortDirection || 'DESC'}
            onChange={handleSortDirectionChange}
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          >
            <option value="ASC">오름차순</option>
            <option value="DESC">내림차순</option>
          </select>
        </div>
      </div>

      {/* 필터 초기화 버튼 */}
      <div className="flex justify-end">
        <button
          onClick={onReset}
          className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition-colors"
        >
          필터 초기화
        </button>
      </div>
    </div>
  );
};

export default HostListFilters;

