import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Manual,
  ManualCategory,
  ManualFilterParams,
} from '../types';
import { getManualList, deleteManual } from '../utils/manualApi';
import { getManualCategoryList } from '../utils/manualCategoryApi';
import { useToast } from '../hooks/useToast';
import LoadingSpinner from '../components/LoadingSpinner';
import ErrorMessage from '../components/ErrorMessage';
import ManualFilters from '../components/ManualFilters';
import ManualCategoryAccordion from '../components/ManualCategoryAccordion';
import ManualDeleteConfirmModal from '../components/ManualDeleteConfirmModal';

const ManualPage: React.FC = () => {
  const navigate = useNavigate();
  const [manuals, setManuals] = useState<Manual[]>([]);
  const [categories, setCategories] = useState<ManualCategory[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  
  const [filters, setFilters] = useState<ManualFilterParams>({
    page: 0,
    size: 1000, // 카테고리별로 표시하므로 큰 값으로 설정
  });

  // 아코디언 확장 상태 (기본적으로 첫 번째 카테고리만 확장)
  const [expandedCategories, setExpandedCategories] = useState<Set<string>>(new Set());

  // 삭제 확인 모달 상태
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
  const [deletingManual, setDeletingManual] = useState<Manual | null>(null);
  const [isDeleting, setIsDeleting] = useState(false);

  const { showToast } = useToast();

  // 관리자 여부 (임시로 true로 설정, 실제로는 인증 정보에서 가져와야 함)
  const isAdmin = true;

  // 카테고리 목록 조회
  const fetchCategories = useCallback(async () => {
    try {
      const response = await getManualCategoryList();
      if (response.success) {
        const sortedCategories = response.data
          .filter((cat) => cat.isActive)
          .sort((a, b) => a.sortOrder - b.sortOrder);
        setCategories(sortedCategories);
        
        // 첫 번째 카테고리만 확장
        if (sortedCategories.length > 0 && expandedCategories.size === 0) {
          setExpandedCategories(new Set([sortedCategories[0].id]));
        }
      }
    } catch (err) {
      console.error('카테고리 목록 조회 실패:', err);
    }
  }, [expandedCategories.size]);

  // 메뉴얼 목록 조회
  const fetchManuals = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      
      const response = await getManualList(filters);
      if (response.success) {
        // sortOrder로 정렬
        const sortedManuals = response.data.manuals
          .filter((manual) => manual.isActive)
          .sort((a, b) => a.sortOrder - b.sortOrder);
        setManuals(sortedManuals);
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : '메뉴얼 목록을 불러오는데 실패했습니다.';
      setError(errorMessage);
      showToast(errorMessage, 'error');
    } finally {
      setLoading(false);
    }
  }, [filters, showToast]);

  // 초기 로딩
  useEffect(() => {
    fetchCategories();
  }, [fetchCategories]);

  useEffect(() => {
    fetchManuals();
  }, [fetchManuals]);

  // 카테고리별로 그룹화된 메뉴얼
  const manualsByCategory = useMemo(() => {
    const grouped: Record<string, Manual[]> = {};
    categories.forEach((category) => {
      grouped[category.id] = manuals.filter(
        (manual) => manual.categoryId === category.id
      );
    });
    return grouped;
  }, [manuals, categories]);

  // 필터 변경 핸들러
  const handleFilterChange = (newFilters: Partial<ManualFilterParams>) => {
    setFilters(prev => ({
      ...prev,
      ...newFilters,
      page: newFilters.page !== undefined ? newFilters.page : 0,
    }));
  };

  // 필터 초기화
  const handleFilterReset = () => {
    setFilters({
      page: 0,
      size: 1000,
    });
  };

  // 카테고리 토글
  const handleCategoryToggle = (categoryId: string) => {
    setExpandedCategories((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(categoryId)) {
        newSet.delete(categoryId);
      } else {
        newSet.add(categoryId);
      }
      return newSet;
    });
  };

  // 메뉴얼 클릭 핸들러 (상세 페이지로 이동)
  const handleManualClick = (manual: Manual) => {
    navigate(`/manuals/${manual.id}`);
  };

  // 수정 버튼 클릭 핸들러
  const handleEditClick = (manual: Manual) => {
    navigate(`/manuals/${manual.id}/edit`);
  };

  // 삭제 버튼 클릭 핸들러
  const handleDeleteClick = (manual: Manual) => {
    setDeletingManual(manual);
    setDeleteModalOpen(true);
  };

  // 메뉴얼 삭제
  const handleDeleteManual = async () => {
    if (!deletingManual) return;

    try {
      setIsDeleting(true);
      const response = await deleteManual(deletingManual.id);
      if (response.success) {
        showToast('메뉴얼이 성공적으로 삭제되었습니다.', 'success');
        setDeleteModalOpen(false);
        setDeletingManual(null);
        await fetchManuals(); // 목록 새로고침
      }
    } catch (err) {
      showToast(
        err instanceof Error ? err.message : '메뉴얼 삭제에 실패했습니다.',
        'error'
      );
    } finally {
      setIsDeleting(false);
    }
  };

  // 순서 변경 후 목록 새로고침
  const handleReorder = () => {
    fetchManuals();
  };

  return (
    <div className="max-w-7xl mx-auto">
      <div className="mb-6 flex justify-between items-center">
        <h1 className="text-2xl font-bold text-gray-900">메뉴얼</h1>
        <div className="flex gap-2">
          {isAdmin && (
            <>
              <button
                onClick={() => navigate('/manuals/categories')}
                className="px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 transition-colors"
              >
                카테고리 관리
              </button>
              <button
                onClick={() => navigate('/manuals/new')}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
              >
                메뉴얼 작성
              </button>
            </>
          )}
        </div>
      </div>

      {loading && <LoadingSpinner />}

      {error && (
        <ErrorMessage message={error} onRetry={fetchManuals} />
      )}

      {!loading && !error && (
        <>
          {/* 필터 영역 */}
          <ManualFilters
            filters={filters}
            categories={categories}
            onFilterChange={handleFilterChange}
            onReset={handleFilterReset}
          />

          {/* 카테고리별 메뉴얼 목록 */}
          {categories.length > 0 ? (
            <div className="space-y-4">
              {categories.map((category) => (
                <ManualCategoryAccordion
                  key={category.id}
                  category={category}
                  manuals={manualsByCategory[category.id] || []}
                  isExpanded={expandedCategories.has(category.id)}
                  isAdmin={isAdmin}
                  onToggle={handleCategoryToggle}
                  onManualClick={handleManualClick}
                  onManualEdit={handleEditClick}
                  onManualDelete={handleDeleteClick}
                  onReorder={handleReorder}
                />
              ))}
            </div>
          ) : (
            <div className="bg-white rounded-lg shadow-sm p-8 text-center">
              <p className="text-gray-600">등록된 카테고리가 없습니다.</p>
            </div>
          )}
        </>
      )}

      {/* 삭제 확인 모달 */}
      <ManualDeleteConfirmModal
        isOpen={deleteModalOpen}
        title={deletingManual?.title || ''}
        onConfirm={handleDeleteManual}
        onCancel={() => {
          setDeleteModalOpen(false);
          setDeletingManual(null);
        }}
        isProcessing={isDeleting}
      />
    </div>
  );
};

export default ManualPage;
