import React, { useState, useRef } from 'react';

interface BusinessRegistrationUploadFormProps {
  currentBusinessRegistrationUrl: string | null;
  onUpload: (file: File, specialNote?: string) => Promise<void>;
  onDelete: () => Promise<void>;
  isUploading: boolean;
  isDeleting: boolean;
  onImageClick?: () => void;
}

const BusinessRegistrationUploadForm: React.FC<BusinessRegistrationUploadFormProps> = ({
  currentBusinessRegistrationUrl,
  onUpload,
  onDelete,
  isUploading,
  isDeleting,
  onImageClick,
}) => {
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [specialNote, setSpecialNote] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // 파일 크기 검증 (100MB)
    const maxSize = 100 * 1024 * 1024;
    if (file.size > maxSize) {
      alert('파일 크기는 100MB를 초과할 수 없습니다.');
      return;
    }

    // 파일 타입 검증 (이미지 및 PDF)
    const allowedTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/gif', 'image/webp', 'application/pdf'];
    if (!allowedTypes.includes(file.type)) {
      alert('이미지 파일 또는 PDF만 업로드할 수 있습니다. (jpg, jpeg, png, gif, webp, pdf)');
      return;
    }

    setSelectedFile(file);

    // 모든 파일 타입에 대해 미리보기 생성 (이미지와 PDF 모두)
    const reader = new FileReader();
    reader.onloadend = () => {
      setPreviewUrl(reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  const handleUpload = async () => {
    if (!selectedFile) return;

    try {
      await onUpload(selectedFile, specialNote.trim() || undefined);
      // 업로드 성공 후 초기화
      setSelectedFile(null);
      setPreviewUrl(null);
      setSpecialNote('');
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    } catch (error) {
      // 에러는 상위 컴포넌트에서 처리
    }
  };

  const handleCancel = () => {
    setSelectedFile(null);
    setPreviewUrl(null);
    setSpecialNote('');
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const handleDelete = async () => {
    if (!currentBusinessRegistrationUrl) return;

    if (window.confirm('사업자등록증을 삭제하시겠습니까?')) {
      try {
        await onDelete();
      } catch (error) {
        // 에러는 상위 컴포넌트에서 처리
      }
    }
  };

  return (
    <div className="space-y-4">
      {/* 현재 사업자등록증 */}
      {currentBusinessRegistrationUrl && !selectedFile && (
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            현재 사업자등록증
          </label>
          <div className="flex items-start gap-4">
            {currentBusinessRegistrationUrl.toLowerCase().endsWith('.pdf') || currentBusinessRegistrationUrl.includes('application/pdf') ? (
              <iframe
                src={currentBusinessRegistrationUrl}
                className="w-full h-96 border border-gray-300 rounded-lg cursor-pointer hover:opacity-80 transition-opacity"
                title="현재 사업자등록증"
                onClick={onImageClick}
              />
            ) : (
              <img
                src={currentBusinessRegistrationUrl}
                alt="현재 사업자등록증"
                className="w-48 h-48 object-contain border border-gray-300 rounded-lg cursor-pointer hover:opacity-80 transition-opacity"
                onClick={onImageClick}
              />
            )}
            <button
              onClick={handleDelete}
              disabled={isDeleting || isUploading}
              className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {isDeleting ? '삭제 중...' : '삭제'}
            </button>
          </div>
        </div>
      )}

      {/* 파일 선택 */}
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-2">
          새 사업자등록증 업로드
        </label>
        <input
          ref={fileInputRef}
          type="file"
          accept="image/jpeg,image/jpg,image/png,image/gif,image/webp,application/pdf"
          onChange={handleFileSelect}
          className="block w-full text-sm text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-lg file:border-0 file:text-sm file:font-semibold file:bg-blue-50 file:text-blue-700 hover:file:bg-blue-100"
          disabled={isUploading || isDeleting}
        />
        <p className="mt-1 text-xs text-gray-500">
          이미지 파일 또는 PDF만 업로드 가능합니다. (최대 100MB)
        </p>
      </div>

      {/* 미리보기 */}
      {previewUrl && selectedFile && (
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            미리보기
          </label>
          {selectedFile.type === 'application/pdf' ? (
            <iframe
              src={previewUrl}
              className="w-full h-96 border border-gray-300 rounded-lg"
              title="PDF 미리보기"
            />
          ) : (
            <img
              src={previewUrl}
              alt="미리보기"
              className="w-48 h-48 object-contain border border-gray-300 rounded-lg"
            />
          )}
        </div>
      )}

      {/* 특이사항 메모 */}
      {selectedFile && (
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            특이사항 메모 (선택)
          </label>
          <textarea
            value={specialNote}
            onChange={(e) => setSpecialNote(e.target.value)}
            placeholder="사업자등록증 업로드 관련 특이사항을 입력하세요."
            rows={3}
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent resize-none"
            disabled={isUploading || isDeleting}
          />
        </div>
      )}

      {/* 업로드 버튼 */}
      {selectedFile && (
        <div className="flex gap-3">
          <button
            onClick={handleUpload}
            disabled={isUploading || isDeleting}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isUploading ? '업로드 중...' : '업로드'}
          </button>
          <button
            onClick={handleCancel}
            disabled={isUploading || isDeleting}
            className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            취소
          </button>
        </div>
      )}
    </div>
  );
};

export default BusinessRegistrationUploadForm;

