import React, { useRef, useEffect } from 'react';

interface HostDocumentModalProps {
  isOpen: boolean;
  bankbookUrl: string | null;
  businessRegistrationUrl: string | null;
  onClose: () => void;
}

const HostDocumentModal: React.FC<HostDocumentModalProps> = ({
  isOpen,
  bankbookUrl,
  businessRegistrationUrl,
  onClose,
}) => {
  const modalRef = useRef<HTMLDivElement>(null);

  // 외부 클릭 감지
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (modalRef.current && !modalRef.current.contains(event.target as Node)) {
        onClose();
      }
    };

    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [isOpen, onClose]);

  // ESC 키 감지
  useEffect(() => {
    const handleEscapeKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        onClose();
      }
    };

    if (isOpen) {
      document.addEventListener('keydown', handleEscapeKey);
    }

    return () => {
      document.removeEventListener('keydown', handleEscapeKey);
    };
  }, [isOpen, onClose]);

  if (!isOpen) {
    return null;
  }

  const hasAnyDocument = bankbookUrl || businessRegistrationUrl;

  return (
    <>
      {/* 배경 딤 */}
      <div className="fixed inset-0 bg-black bg-opacity-75 z-50 flex items-center justify-center p-4">
        {/* 모달 */}
        <div
          ref={modalRef}
          className="bg-white rounded-lg shadow-xl max-w-6xl w-full max-h-[90vh] animate-fade-in relative flex flex-col"
        >
          {/* 헤더 */}
          <div className="flex items-center justify-between p-4 border-b border-gray-200">
            <h3 className="text-lg font-semibold text-gray-900">호스트 서류</h3>
            <button
              onClick={onClose}
              className="text-gray-400 hover:text-gray-600 transition-colors"
              aria-label="모달 닫기"
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>

          {/* 내용 */}
          <div className="flex-1 overflow-y-auto p-6">
            {hasAnyDocument ? (
              <div className="flex flex-col md:flex-row gap-6">
                {/* 통장사본 */}
                <div className="flex-1">
                  <h4 className="text-md font-semibold text-gray-900 mb-3">통장사본</h4>
                  {bankbookUrl ? (
                    <div className="border border-gray-200 rounded-lg overflow-hidden bg-gray-50">
                      {bankbookUrl.toLowerCase().endsWith('.pdf') || bankbookUrl.includes('application/pdf') ? (
                        <iframe
                          src={bankbookUrl}
                          className="w-full h-[60vh] min-h-[400px]"
                          title="통장사본 PDF"
                        />
                      ) : (
                        <img
                          src={bankbookUrl}
                          alt="통장사본"
                          className="w-full h-auto object-contain max-h-[60vh]"
                          onError={(e) => {
                            const target = e.target as HTMLImageElement;
                            target.style.display = 'none';
                            const parent = target.parentElement;
                            if (parent) {
                              parent.innerHTML = '<div class="p-8 text-center text-gray-500">이미지를 불러올 수 없습니다.</div>';
                            }
                          }}
                        />
                      )}
                    </div>
                  ) : (
                    <div className="border border-gray-200 rounded-lg p-8 text-center text-gray-500 bg-gray-50">
                      통장사본이 없습니다.
                    </div>
                  )}
                </div>

                {/* 사업자등록증 */}
                <div className="flex-1">
                  <h4 className="text-md font-semibold text-gray-900 mb-3">사업자등록증</h4>
                  {businessRegistrationUrl ? (
                    <div className="border border-gray-200 rounded-lg overflow-hidden bg-gray-50">
                      {businessRegistrationUrl.toLowerCase().endsWith('.pdf') || businessRegistrationUrl.includes('application/pdf') ? (
                        <iframe
                          src={businessRegistrationUrl}
                          className="w-full h-[60vh] min-h-[400px]"
                          title="사업자등록증 PDF"
                        />
                      ) : (
                        <img
                          src={businessRegistrationUrl}
                          alt="사업자등록증"
                          className="w-full h-auto object-contain max-h-[60vh]"
                          onError={(e) => {
                            const target = e.target as HTMLImageElement;
                            target.style.display = 'none';
                            const parent = target.parentElement;
                            if (parent) {
                              parent.innerHTML = '<div class="p-8 text-center text-gray-500">이미지를 불러올 수 없습니다.</div>';
                            }
                          }}
                        />
                      )}
                    </div>
                  ) : (
                    <div className="border border-gray-200 rounded-lg p-8 text-center text-gray-500 bg-gray-50">
                      사업자등록증이 없습니다.
                    </div>
                  )}
                </div>
              </div>
            ) : (
              <div className="text-center py-16 text-gray-500">
                표시할 서류가 없습니다.
              </div>
            )}
          </div>
        </div>
      </div>
    </>
  );
};

export default HostDocumentModal;
