import React from 'react';

interface StatusFilterProps {
  showPreparedOrders: boolean;
  onToggle: (showPrepared: boolean) => void;
  paidCount: number;
  preparedCount: number;
}

const StatusFilter: React.FC<StatusFilterProps> = ({ 
  showPreparedOrders, 
  onToggle, 
  paidCount, 
  preparedCount 
}) => {
  return (
    <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-4 mb-4">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-md font-medium text-gray-900">주문 상태 필터</h3>
          <p className="text-sm text-gray-600">
            {showPreparedOrders 
              ? `모든 상태 주문 ${paidCount + preparedCount}건 표시 중` 
              : `결제완료 주문 ${paidCount}건 표시 중`
            }
          </p>
        </div>
        
        <div className="flex bg-gray-100 rounded-lg p-1">
          <button
            onClick={() => onToggle(false)}
            className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${
              !showPreparedOrders
                ? 'bg-blue-600 text-white shadow-sm'
                : 'text-gray-600 hover:text-gray-900'
            }`}
          >
            결제완료만
            <span className="ml-1 text-xs">({paidCount})</span>
          </button>
          <button
            onClick={() => onToggle(true)}
            className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${
              showPreparedOrders
                ? 'bg-blue-600 text-white shadow-sm'
                : 'text-gray-600 hover:text-gray-900'
            }`}
          >
            모든 상태
            <span className="ml-1 text-xs">({paidCount + preparedCount})</span>
          </button>
        </div>
      </div>
    </div>
  );
};

export default StatusFilter; 