// 통장사본 업로드
export const uploadBankbook = async (
  hostId: string,
  imageFile: File,
  specialNote?: string
): Promise<BankbookUploadResponse> => {
  const url = `${API_BASE_URL}/api/hosts/${hostId}/bankbook`;
  
  // 파일 크기 검증 (100MB)
  const maxSize = 100 * 1024 * 1024; // 100MB
  if (imageFile.size > maxSize) {
    throw new Error('파일 크기는 100MB를 초과할 수 없습니다.');
  }

  // 파일 타입 검증 (이미지 및 PDF)
  const allowedTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/gif', 'image/webp', 'application/pdf'];
  if (!allowedTypes.includes(imageFile.type)) {
    throw new Error('이미지 파일 또는 PDF만 업로드할 수 있습니다. (jpg, jpeg, png, gif, webp, pdf)');
  }

  try {
    const formData = new FormData();
    formData.append('image', imageFile);
    if (specialNote) {
      formData.append('specialNote', specialNote);
    }

    const response = await fetch(url, {
      method: 'PUT',
      headers: {
        'X-SERVER-AUTH': 'secret',
        // FormData 사용 시 Content-Type 헤더를 설정하지 않음 (브라우저가 자동 설정)
      },
      mode: 'cors',
      body: formData,
    });

    if (!response.ok) {
      if (response.status === 400) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.message || '파일 업로드에 실패했습니다. 파일을 확인해주세요.');
      }
      handleResponseError(response);
    }

    return response.json();
  } catch (error) {
    if (error instanceof Error && (error.message.includes('파일 크기') || error.message.includes('이미지 파일') || error.message.includes('PDF'))) {
      throw error;
    }
    handleNetworkError(error);
    throw error;
  }
};

