import React, { useState } from 'react';
import {
  DndContext,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragEndEvent,
} from '@dnd-kit/core';
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
  useSortable,
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { Manual } from '../types';
import ManualCard from './ManualCard';
import { reorderManual } from '../utils/manualApi';
import { useToast } from '../hooks/useToast';

interface ManualListProps {
  manuals: Manual[];
  isAdmin?: boolean;
  onManualClick?: (manual: Manual) => void;
  onManualEdit?: (manual: Manual) => void;
  onManualDelete?: (manual: Manual) => void;
  onReorder?: () => void; // 순서 변경 후 목록 새로고침 콜백
}

interface SortableManualItemProps {
  manual: Manual;
  isAdmin?: boolean;
  onManualClick?: (manual: Manual) => void;
  onManualEdit?: (manual: Manual) => void;
  onManualDelete?: (manual: Manual) => void;
}

const SortableManualItem: React.FC<SortableManualItemProps> = ({
  manual,
  isAdmin,
  onManualClick,
  onManualEdit,
  onManualDelete,
}) => {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: manual.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  };

  return (
    <div ref={setNodeRef} style={style}>
      <div className="flex items-center gap-2">
        {isAdmin && (
          <div
            {...attributes}
            {...listeners}
            className="cursor-grab active:cursor-grabbing text-gray-400 hover:text-gray-600 p-2"
            title="드래그하여 순서 변경"
          >
            <svg
              className="w-5 h-5"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M4 8h16M4 16h16"
              />
            </svg>
          </div>
        )}
        <div className="flex-1">
          <ManualCard
            manual={manual}
            isAdmin={isAdmin}
            onClick={() => onManualClick?.(manual)}
            onEdit={onManualEdit}
            onDelete={onManualDelete}
          />
        </div>
      </div>
    </div>
  );
};

const ManualList: React.FC<ManualListProps> = ({
  manuals,
  isAdmin = false,
  onManualClick,
  onManualEdit,
  onManualDelete,
  onReorder,
}) => {
  const [items, setItems] = useState<Manual[]>(manuals);
  const { showToast } = useToast();

  // sensors 설정
  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  // manuals prop이 변경되면 items 업데이트
  React.useEffect(() => {
    setItems(manuals);
  }, [manuals]);

  // 드래그 종료 핸들러
  const handleDragEnd = async (event: DragEndEvent) => {
    const { active, over } = event;

    if (!over || active.id === over.id) {
      return;
    }

    const oldIndex = items.findIndex((item) => item.id === active.id);
    const newIndex = items.findIndex((item) => item.id === over.id);

    if (oldIndex === -1 || newIndex === -1) {
      return;
    }

    // 낙관적 업데이트: UI를 먼저 업데이트
    const newItems = arrayMove(items, oldIndex, newIndex);
    setItems(newItems);

    // API 호출
    const movedManual = newItems[newIndex];
    const newSortOrder = newIndex + 1; // 1부터 시작

    try {
      await reorderManual(movedManual.id, { newSortOrder });
      showToast('순서가 변경되었습니다.', 'success');
      // 순서 변경 후 목록 새로고침
      onReorder?.();
    } catch (error) {
      // 실패 시 원래 순서로 복구
      setItems(manuals);
      showToast(
        error instanceof Error
          ? error.message
          : '순서 변경에 실패했습니다.',
        'error'
      );
    }
  };

  if (items.length === 0) {
    return (
      <div className="text-center py-8 text-gray-500">
        메뉴얼이 없습니다.
      </div>
    );
  }

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={closestCenter}
      onDragEnd={handleDragEnd}
    >
      <SortableContext
        items={items.map((item) => item.id)}
        strategy={verticalListSortingStrategy}
      >
        <div className="space-y-2">
          {items.map((manual) => (
            <SortableManualItem
              key={manual.id}
              manual={manual}
              isAdmin={isAdmin}
              onManualClick={onManualClick}
              onManualEdit={onManualEdit}
              onManualDelete={onManualDelete}
            />
          ))}
        </div>
      </SortableContext>
    </DndContext>
  );
};

export default ManualList;
